import pandas as pd
import numpy as np

train = pd.read_csv('/app/data/train.csv')

# Check feature sparsity - how many zeros
num_cols = [c for c in train.columns if c.startswith('num_')]
zero_fracs = {}
for c in num_cols:
    zero_frac = (train[c] == 0).mean()
    if zero_frac > 0.5:
        zero_fracs[c] = zero_frac

print("Features with >50% zeros (sparse):")
for c, frac in sorted(zero_fracs.items(), key=lambda x: -x[1]):
    print(f"  {c}: {frac:.4f}")
